void bubble_sort(int* a, size_t n) {
    if (n < 2) return;
    for (size_t i = 0; i < n - 1; ++i) {
        for (size_t j = 0; j < n - i - 1; ++j) {
            if (a[j] > a[j + 1]) {
                int temp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = temp;
            }
        }
    }
}

static void merge(int* a, size_t left, size_t mid, size_t right) {
    size_t n1 = mid - left + 1;
    size_t n2 = right - mid;

    int* L = (int*)std::malloc(n1 * sizeof(int));
    int* R = (int*)std::malloc(n2 * sizeof(int));

    for (size_t i = 0; i < n1; ++i) L[i] = a[left + i];
    for (size_t j = 0; j < n2; ++j) R[j] = a[mid + 1 + j];

    size_t i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            a[k++] = L[i++];
        } else {
            a[k++] = R[j++];
        }
    }

    while (i < n1) a[k++] = L[i++];
    while (j < n2) a[k++] = R[j++];

    std::free(L);
    std::free(R);
}

static void merge_sort_recursive(int* a, size_t left, size_t right) {
    if (left < right) {
        size_t mid = left + (right - left) / 2;
        merge_sort_recursive(a, left, mid);
        merge_sort_recursive(a, mid + 1, right);
        merge(a, left, mid, right);
    }
}

void merge_sort(int* a, size_t n) {
    if (n < 2) return;
    merge_sort_recursive(a, 0, n - 1);
}
